    // Check if the stream was successfully read
    if (pvrerror() != 0) {
        std::cerr << "Error reading pvr stream: " << pvrerror() << std::endl;
        return 1;
    }

    // Decompress pvr data to raw format
    pvrdecode(stream, 0, pvrdecode_size_t(8888));

    // Print decompressed data
    std::cout << "Decompressed data in raw format: " << std::hex << pvrdata() << std::endl;

    return 0;
}
